-- Generated by Ergasterion from a product declaration. Do not edit by hand.
{{ config(materialized='table') }}

with
quarantined as (
    select
        order_line_record_id,
        order_id,
        order_line_source_product_id,
        line_number,
        line_quantity,
        line_unit_price,
        line_revenue,
        line_currency,
        line_order_date,
        order_line_source_system,
        product_code,
        violation_00,
        violation_01
    from {{ ref("ecommerce__order_line__checked") }}
),
violations as (
    select
        'order_line_record_id_not_null' as rule_name,
        order_line_record_id,
        order_id,
        order_line_source_product_id,
        line_number,
        line_quantity,
        line_unit_price,
        line_revenue,
        line_currency,
        line_order_date,
        order_line_source_system,
        product_code
    from quarantined
    where violation_00

    union all

    select
        'order_id_not_null' as rule_name,
        order_line_record_id,
        order_id,
        order_line_source_product_id,
        line_number,
        line_quantity,
        line_unit_price,
        line_revenue,
        line_currency,
        line_order_date,
        order_line_source_system,
        product_code
    from quarantined
    where violation_01
)

select
    rule_name,
    order_line_record_id,
    order_id,
    order_line_source_product_id,
    line_number,
    line_quantity,
    line_unit_price,
    line_revenue,
    line_currency,
    line_order_date,
    order_line_source_system,
    product_code
from violations
